let reader;
async function getReader(){if(!reader)reader=(async()=>{const {modelStore}=await import('./model-storage.mjs');await modelStore.requireInstalled('en');const {pipeline,env}=await import('./vendor/recognition/transformers.min.js');env.allowLocalModels=true;env.allowRemoteModels=false;env.useBrowserCache=false;env.useFSCache=false;env.useCustomCache=true;env.customCache={match:url=>modelStore.responseFor(url),put:async()=>{}};env.backends.onnx.wasm.numThreads=1;env.backends.onnx.wasm.proxy=false;env.backends.onnx.wasm.wasmPaths=new URL('./vendor/recognition/',self.location).href;const config=await (await fetch(new URL('./vendor/recognition/model.json',self.location))).json();return pipeline('image-to-text',config.model,{revision:config.revision,dtype:'q8',device:'wasm',progress_callback:p=>self.postMessage({type:'progress',status:p.status,file:p.file,progress:p.progress})});})().catch(e=>{reader=null;throw e;});return reader;}
self.onmessage=async({data:m})=>{try{if(m.language==='mr'){const {recognizeDevanagari}=await import('./devanagari-recognizer.mjs');const result=await recognizeDevanagari(new Uint8ClampedArray(m.pixels),m.width,m.height,p=>self.postMessage({type:'progress',...p}));self.postMessage({type:'result',id:m.id,...result});return;}const pipe=await getReader(),{RawImage}=await import('./vendor/recognition/transformers.min.js');const image=new RawImage(new Uint8ClampedArray(m.pixels),m.width,m.height,4),result=await pipe(image,{max_new_tokens:96,num_beams:3,num_return_sequences:3});self.postMessage({type:'result',id:m.id,text:result[0]?.generated_text||'',alternatives:result.slice(1,3).map(r=>r.generated_text||'')});}catch(e){self.postMessage({type:'error',id:m.id,error:e.message});}};
